## Why This Is Asked
Tests a beginner-friendly DP pattern with non-adjacent selections and reconstruction. It also shows handling multiple dimensions (i and t) and a simple heuristic constraint (no two boosts on consecutive days).

## Key Concepts
- DP with two states per index for constrained selections
- Reconstruction of chosen days
- Time/space: O(nk); note can optimize to O(k) space with rolling arrays

## Code Example
```javascript
function maxWorkload(workload, k) {
  const n = workload.length;
  const NEG = -1e15;
  const noBoost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  const boost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  noBoost[0][0] = workload[0];
  if (k >= 1) boost[0][1] = 2 * workload[0];
  for (let i = 1; i < n; i++) {
    for (let t = 0; t <= k; t++) {
      noBoost[i][t] = Math.max(noBoost[i-1][t], boost[i-1][t]) + workload[i];
    }
    for (let t = 1; t <= k; t++) {
      if (noBoost[i-1][t-1] > NEG) boost[i][t] = noBoost[i-1][t-1] + 2*workload[i];
    }
  }
  let best = NEG, bestT = 0, bestS = 0;
  for (let t = 0; t <= k; t++) {
    if (noBoost[n-1][t] > best) { best = noBoost[n-1][t]; bestT = t; bestS = 0; }
    if (boost[n-1][t] > best) { best = boost[n-1][t]; bestT = t; bestS = 1; }
  }
  // reconstruction would backtrack using saved states (omitted for brevity)
  return { maxValue: best, boostedIndices: [] };
}
```

## Why This Is Asked
Tests DP partitioning with a non-sum objective and reconstruction requirements.

## Key Concepts
- DP over partitions with dp[i][t]
- Precomputing max-min for all subarrays
- Path reconstruction via parent pointers

## Code Example
```javascript
function maxMinSubarrayVal(arr){
  const n = arr.length;
  const maxVal = Array.from({length:n}, ()=>Array(n).fill(0));
  const minVal = Array.from({length:n}, ()=>Array(n).fill(0));
  for(let i=0;i<n;i++){
    let curMax = arr[i], curMin = arr[i];
    for(let j=i;j<n;j++){
      curMax = Math.max(curMax, arr[j]);
      curMin = Math.min(curMin, arr[j]);
      maxVal[i][j] = curMax;
      minVal[i][j] = curMin;
    }
  }
  const val = (l,r)=> maxVal[l][r] - minVal[l][r];
  return val;
}

function bestPartition(arr, k){
  const n = arr.length;
  const val = maxMinSubarrayVal(arr);
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const parent = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for(let i=1;i<=n;i++) dp[i][1] = val(0,i-1);
  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<=i-1;j++){
        const cand = dp[j][t-1] + val(j, i-1);
        if(cand > dp[i][t]){ dp[i][t] = cand; parent[i][t]=j; }
      }
    }
  }
  // reconstruct
  let blocks = [];
  let i=n, t=k;
  while(t>0){
    const j = parent[i][t];
    blocks.push([j, i-1]);
    i = j; t--;
  }
  blocks.reverse();
  return {value: dp[n][k], blocks};
}
```

